<section class="page-header"><div><span class="eyebrow">Personal notification centre</span><h1>Notifications</h1><p>Assignments, reminders, approvals, attendance, payroll and billing updates.</p></div><div class="page-actions"><button class="button button-secondary" type="button" id="enableBrowserNotifications"><i class="fa-regular fa-window-restore"></i> Enable browser alerts</button><form method="post" action="<?= url('notifications/read-all') ?>"><?= csrf_field() ?><button class="button button-secondary"><i class="fa-solid fa-check-double"></i> Mark all read</button></form></div></section><section class="panel notification-page-list"><?php foreach($rows as $row):?><article class="notification-page-item <?= $row['read_at']?'read':'' ?>"><span class="notification-page-icon"><i class="fa-solid fa-<?= str_contains($row['type'],'task')?'list-check':(str_contains($row['type'],'payment')?'indian-rupee-sign':'bell') ?>"></i></span><div><strong><?= e($row['title']) ?></strong><p><?= e($row['message']) ?></p><small><?= e(date('d M Y, g:i A',strtotime($row['created_at']))) ?></small></div><?php if($row['link']):?><a class="button button-ghost button-sm" href="<?= url(ltrim($row['link'],'/')) ?>">Open</a><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><div class="empty-state"><span><i class="fa-regular fa-bell-slash"></i></span><h3>No notifications</h3><p>You are all caught up.</p></div><?php endif;?></section>
